from __future__ import annotations
from typing import Optional, Tuple

def step(p: str, s: int) -> Optional[Tuple[str, int]]:
    """One self-modifying step: the program name flips every step."""
    if s <= 0:
        return None
    return ("B" if p == "A" else "A", s - 1)

def trace_smm(start: Tuple[str, int], budget: int) -> None:
    cfg: Optional[Tuple[str, int]] = start
    for t in range(budget + 1):
        if cfg is None:
            print(f"  t={t}: HALTED")
            return
        print(f"  t={t}: program={cfg[0]!r} state={cfg[1]}")
        cfg = step(cfg[0], cfg[1])
    print("  (budget exhausted, still running)")

def flattened_step(ps: Tuple[str, int]) -> Optional[Tuple[str, int]]:
    """The 'code becomes data' fixed-program simulation."""
    return step(ps[0], ps[1])

def runs_agree(start: Tuple[str, int], budget: int) -> bool:
    a: Optional[Tuple[str, int]] = start
    b: Optional[Tuple[str, int]] = start
    for _ in range(budget):
        if a != b:
            return False
        a = None if a is None else step(a[0], a[1])
        b = None if b is None else flattened_step(b)
    return a == b

if __name__ == "__main__":
    print("Trace of the self-rewriting machine from ('A', 4):")
    trace_smm(("A", 4), 8)
    print("SMM run == flattened simulation run:", runs_agree(("A", 4), 20))

from __future__ import annotations
from typing import Callable, Optional, Tuple

def smm_run(step: Callable[[str, int], Optional[Tuple[str, int]]],
            cfg: Tuple[str, int], n: int) -> Optional[Tuple[str, int]]:
    for _ in range(n):
        nxt = step(cfg[0], cfg[1])
        if nxt is None:
            return None
        cfg = nxt
    return cfg

def std_run(step: Callable[[int], Optional[int]], s: int, n: int) -> Optional[int]:
    for _ in range(n):
        nxt = step(s)
        if nxt is None:
            return None
        s = nxt
    return s

def halts_smm(step, cfg, budget) -> bool:
    return any(smm_run(step, cfg, n) is None for n in range(budget + 1))

def halts_std(step, s, budget) -> bool:
    return any(std_run(step, s, n) is None for n in range(budget + 1))

# self-modifying instance
smm_step = lambda p, s: None if s <= 0 else (("B" if p == "A" else "A"), s - 1)
# its flattened simulation is a standard machine over (program, state)
sim_step = lambda ps: smm_step(ps[0], ps[1])

if __name__ == "__main__":
    for cfg in [("A", 4), ("B", 0), ("A", 7)]:
        h1 = halts_smm(smm_step, cfg, 30)
        # forward reduction is the identity (prog,state)
        h2 = any(std_run(sim_step, cfg, n) is None for n in range(31))
        print(f"forward  cfg={cfg}: smm={h1}  sim={h2}  preserved={h1==h2}")
    base = lambda s: None if s <= 0 else s - 1
    emb = lambda p, s: None if base(s) is None else (None, base(s))
    for s in [0, 1, 5, 9]:
        h1 = halts_std(base, s, 30)
        h2 = halts_smm(emb, (None, s), 30)  # backward reduction s -> ((), s)
        print(f"backward s={s}: std={h1}  emb={h2}  preserved={h1==h2}")

