function BoundedSimulate(step, prog, state, N):
    data <- (prog, state)          # code becomes data
    for t in 0 .. N-1:
        result <- step(data.prog, data.state)
        if result = HALT:
            return HALTED at step t
        else:
            (prog', state') <- result
            data <- (prog', state')  # write rewritten program back
    return RUNNING (inconclusive)

function BuildContrarian(H):
    define d(q):
        verdict <- H(q, q)          # ask H what q does on itself
        if verdict = TRUE:
            loop forever            # do the opposite
        else:
            halt
    return d

# Consequence: running d on its own code, H(d,d) must equal not H(d,d).

function ReduceSelfModToStd(cfg):
    return (cfg.prog, cfg.state)      # identity as data

function ReduceStdToSelfMod(s):
    return (UNIT, s)                  # trivial one-point program

