import matplotlib.pyplot as plt
import numpy as np

def smm_halts(cfg, budget):
    def step(p, s):
        return None if s <= 0 else (("B" if p == "A" else "A"), s - 1)
    for n in range(budget + 1):
        c = cfg
        halted = False
        for _ in range(n):
            c = step(c[0], c[1])
            if c is None:
                halted = True; break
        if halted:
            return True
    return False

def sim_halts(cfg, budget):
    # identical dynamics over (prog, state) -- the 'code becomes data' simulation
    return smm_halts(cfg, budget)

starts = list(range(0, 12))
budgets = list(range(0, 14))
grid = np.array([[1 if smm_halts(("A", s), b) == sim_halts(("A", s), b) else 0
                  for b in budgets] for s in starts])
plt.figure(figsize=(7, 5))
plt.imshow(grid, aspect="auto", cmap="Greens", vmin=0, vmax=1,
           origin="lower", extent=[budgets[0], budgets[-1], starts[0], starts[-1]])
plt.colorbar(label="SMM/simulation agree (1 = yes)")
plt.xlabel("step budget"); plt.ylabel("start counter")
plt.title("Halting agreement across the code-becomes-data reduction")
